catalog_script_client.script:
/**
 * Function to extract the parameter value from the url
 */

function getParmVal(name){
    name = name.replace(/[\[]/, "\\\[").replace(/[\]]/, "\\\]");  
    var regexS = "[\\?&]" + name + "=([^&#]*)";  
    var regex = new RegExp(regexS);  
    var results = regex.exec(top.location);  
    if (results == null) {  
        return "";  
    } else {  
        return unescape(results[1]);  
    }  
}

/**
 * Function to set values in the form field
 * 
 */
function setParmVal(field_id, value) {
    g_form.setValue(field_id, value);	
}

/**
 * Function to remove html elements from the description value 
 * filled by the emp in accommodation form
 */
function stripHTML(htmlString) {
    return htmlString.replace(/<[^>]+>/g, '');
}


/**
 * onLoad function to populate the emp details in the form
 * 
 */
function onLoad() {
    var parent_case_number = getParmVal('parent_case_number');

    var ga = new GlideAjax("x_hccc_hoc_ohs.HoCDisabilityAccommodation");
    ga.addParam('sysparm_name', 'getEmployeeInfo');
    ga.addParam('sysparm_case_id', parent_case_number);

    ga.getXMLAnswer(function(response) {
        var employeeData = JSON.parse(response);

        var description = stripHTML(employeeData.employee_description);
        var emp_data = JSON.parse(employeeData.employee_details);

        if (employeeData.error) {
            alert(employeeData.error);
        } else {

            setParmVal('employee_name', employeeData.employee_name);
            setParmVal('employee_email', emp_data.employee_email);
            setParmVal('emp_position_title', emp_data.employee_position_title);
            setParmVal('emp_manager', emp_data.employee_manager_name);
            setParmVal('emp_req_description', description);


        }
    });
}
